import{_ as i}from"./chunks/visibility_progress.hOO4BvNJ.js";import{_ as o,c as t,o as r,ae as a}from"./chunks/framework.CliRSA9F.js";const m=JSON.parse('{"title":"Visibility Score Explained","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/visibility-score-explained.md","filePath":"getting-started/visibility-score-explained.md"}'),s={name:"getting-started/visibility-score-explained.md"};function n(l,e,c,h,d,g){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="visibility-score-explained" tabindex="-1">Visibility Score Explained <a class="header-anchor" href="#visibility-score-explained" aria-label="Permalink to &quot;Visibility Score Explained&quot;">​</a></h1><h2 id="what-is-the-visibility-score" tabindex="-1">What is the Visibility Score? <a class="header-anchor" href="#what-is-the-visibility-score" aria-label="Permalink to &quot;What is the Visibility Score?&quot;">​</a></h2><p>The <strong>Visibility Score</strong> is the central metric on your Overview tab under Traction. It measures how discoverable your podcast is across major listening platforms — Apple Podcasts, Spotify, Amazon Music, and YouTube Music — on a <strong>0 to 10 scale</strong>.</p><p>A higher score means your podcast is easier to find: through search results, chart placements, and editorial features. The score updates regularly, so you can track the direct impact of your optimization efforts over time.</p><p><img src="'+i+'" alt="Visibility Score Breakdown" width="600px" style="display:block;margin:0 auto;"></p><hr><h2 id="how-is-the-visibility-score-calculated" tabindex="-1">How is the Visibility Score Calculated? <a class="header-anchor" href="#how-is-the-visibility-score-calculated" aria-label="Permalink to &quot;How is the Visibility Score Calculated?&quot;">​</a></h2><p>The Visibility Score is a composite metric that combines three factors. Each contributes to your overall score, but they don&#39;t all carry the same weight:</p><h3 id="chart-rankings" tabindex="-1"><strong>Chart Rankings</strong> <a class="header-anchor" href="#chart-rankings" aria-label="Permalink to &quot;**Chart Rankings**&quot;">​</a></h3><ul><li>Positions in platform charts across Apple Podcasts, Spotify, Amazon Music, and YouTube Music</li><li>Charts represent platforms actively promoting your podcast to browse-page audiences — this is &quot;push&quot; visibility that reaches listeners who aren&#39;t searching</li><li><strong>Weight</strong>: Highest. Entering or leaving a chart can cause the largest single-day score swings</li></ul><h3 id="editorial-features" tabindex="-1"><strong>Editorial Features</strong> <a class="header-anchor" href="#editorial-features" aria-label="Permalink to &quot;**Editorial Features**&quot;">​</a></h3><ul><li>Appearances in curated collections, featured sections, and editorial recommendations</li><li>Like charts, editorial features represent platform-driven promotion rather than organic search</li><li><strong>Weight</strong>: Highest. Being featured (or losing a feature) has a similar impact to chart changes</li></ul><h3 id="search-score" tabindex="-1"><strong>Search Score</strong> <a class="header-anchor" href="#search-score" aria-label="Permalink to &quot;**Search Score**&quot;">​</a></h3><ul><li>How many keywords your podcast ranks for across all four platforms</li><li>Your ranking position for each keyword (lower = better)</li><li>Ranking alongside popular podcasts matters — if you rank for a keyword where top shows also rank, that&#39;s a stronger signal than ranking for keywords with less competition</li><li><strong>Weight</strong>: Moderate. This is your baseline organic visibility — it changes gradually and is the component you have the most control over through SEO optimization</li></ul><p><strong>In practice</strong>: Most day-to-day score changes come from Search Score shifts. Dramatic jumps or drops are almost always caused by chart or editorial changes.</p><hr><h2 id="what-is-the-visibility-rank" tabindex="-1">What is the Visibility Rank? <a class="header-anchor" href="#what-is-the-visibility-rank" aria-label="Permalink to &quot;What is the Visibility Rank?&quot;">​</a></h2><p>The <strong>Visibility Rank</strong> is derived from your Visibility Score. PodSEO calculates a Visibility Score for every podcast it indexes, then ranks all podcasts from highest to lowest score. Your rank is simply your position in that list.</p><p>A lower rank number means higher visibility: a podcast ranked #25 is more visible than one ranked #250.</p><h3 id="score-vs-rank-what-s-the-difference" tabindex="-1">Score vs. Rank: What&#39;s the Difference? <a class="header-anchor" href="#score-vs-rank-what-s-the-difference" aria-label="Permalink to &quot;Score vs. Rank: What&#39;s the Difference?&quot;">​</a></h3><ul><li><strong>Score</strong> = Your own visibility performance (0-10 scale)</li><li><strong>Rank</strong> = Your position relative to all other indexed podcasts</li></ul><p>For example, your podcast might have a score of 7.1, which puts it at <strong>rank #120</strong>, while another show with a score of 7.2 might be ranked <strong>#95</strong>. Even small score differences can translate to significant rank gaps, especially in competitive ranges where many podcasts cluster around similar scores.</p><p><strong>When to use each</strong>: Track your <strong>score</strong> to measure your own progress over time. Use your <strong>rank</strong> to understand how you compare to the broader podcast landscape.</p><hr><h2 id="why-is-my-score-going-down-even-though-my-downloads-are-increasing" tabindex="-1">Why Is My Score Going Down Even Though My Downloads Are Increasing? <a class="header-anchor" href="#why-is-my-score-going-down-even-though-my-downloads-are-increasing" aria-label="Permalink to &quot;Why Is My Score Going Down Even Though My Downloads Are Increasing?&quot;">​</a></h2><p>This is a common and understandable question. Downloads measure <strong>audience size</strong>, but the Visibility Score measures <strong>discoverability</strong> — how easy it is for new listeners to find you.</p><p>Here are the main reasons your score can decline:</p><ul><li><strong>Chart ranking declines</strong>: Dropped out of or fell in platform-specific charts</li><li><strong>Editorial feature loss</strong>: No longer featured in curated collections or editorial recommendations</li><li><strong>Lost keyword rankings</strong>: Your podcast stopped ranking for keywords it previously ranked for</li><li><strong>Ranking position drops</strong>: You still rank for the same keywords but at lower positions (e.g., from #15 to #35)</li><li><strong>Competitor improvements</strong>: Other podcasts improved their rankings for keywords you compete for</li></ul><p><strong>Key Insight</strong>: Dramatic score changes are usually caused by chart or editorial shifts (entering/leaving a chart, gaining/losing a feature). Gradual changes typically reflect search score movements. Download numbers and audience engagement metrics don&#39;t affect the Visibility Score.</p><p>Remember: More downloads do not always mean better discoverability.</p><hr><h2 id="how-do-i-improve-my-visibility-score" tabindex="-1">How Do I Improve My Visibility Score? <a class="header-anchor" href="#how-do-i-improve-my-visibility-score" aria-label="Permalink to &quot;How Do I Improve My Visibility Score?&quot;">​</a></h2><p>Here are actionable steps:</p><ol><li><strong>Optimize your titles and descriptions</strong> using relevant, high-volume keywords.</li><li><strong>Refresh older episode metadata</strong> to include trending terms and related topics.</li><li><strong>Maintain a consistent publishing cadence</strong> — search platforms favor active shows.</li><li><strong>Improve feed health</strong> by reducing RSS errors, boosting speed, and standardizing formats.</li><li><strong>Track what works</strong>: Use PodSEO&#39;s keyword insights to double down on winning topics.</li></ol><p>For a step-by-step optimization process, follow our <a href="/getting-started/workflow.html">PodSEO Workflow guide</a>.</p><hr><h2 id="how-do-i-find-relevant-competitors" tabindex="-1">How Do I Find Relevant Competitors? <a class="header-anchor" href="#how-do-i-find-relevant-competitors" aria-label="Permalink to &quot;How Do I Find Relevant Competitors?&quot;">​</a></h2><p>PodSEO makes this easy:</p><ul><li>On the <strong>Overview</strong> tab under Traction, use the <strong>&quot;Add Competitor&quot;</strong> button.</li><li>You can search Apple Podcasts and add direct competitors manually.</li><li>Alternatively, PodSEO auto-suggests podcasts that rank for <strong>the same keywords as you</strong>, even if they cover different topics.</li></ul><p>This helps you understand what successful shows in your keyword space are doing — so you can learn, adapt, and improve.</p>',40)])])}const y=o(s,[["render",n]]);export{m as __pageData,y as default};
